"C:\\Program Files\\WindowsApps\\OpenAI.CodexPrimaryRuntime.v26-1104-2876-0_26.1104.2876.0_x64__3k8sg7r9htsxt\\dependencies\\native\\powershell\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$serie = Get-Content -LiteralPath datos/PN09822PM.json -Raw -Encoding UTF8 | ConvertFrom-Json
$meses = '"'Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'
"'$esperados = @(foreach ($anio in 2020..2024) { foreach ($mes in $meses) { "$mes$anio" } })
$periodos = @(foreach ($p in $serie.periods) {
  $etiqueta = [regex]::Match($p.name, '"'"'^([A-Za-z]{3})'"\\.?\\s*(20(?:20|21|22|23|24)|2[0-4])"'$'"')
  if (-not "'$etiqueta.Success) { throw '"'Formato de período inesperado' }
  "'$anio = [int]$etiqueta.Groups[2].Value
  if ($anio -lt 100) { $anio += 2000 }
  if ($p.values.Count -ne 1) { throw '"'Cantidad de valores inesperada' }
  [pscustomobject]@{
    Mes = "'$etiqueta.Groups[1].Value
    Anio = $anio
    Valor = [decimal]::Parse($p.values[0], [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture)
  }
})
$claves = @($periodos | ForEach-Object { "$($_.Mes)$($_.Anio)" })
if ($periodos.Count -ne 60 -or (Compare-Object $esperados $claves)) { throw '"'Cobertura mensual inesperada' }
"'$maximo = ($periodos | Measure-Object -Property Valor -Maximum).Maximum
$picos = @($periodos | Where-Object Valor -eq $maximo)
[pscustomobject]@{MesesVerificados=$periodos.Count; InflacionInteranualMaxima=$maximo; NumeroDeMaximos=$picos.Count; PeriodoDelMaximo=(($picos | ForEach-Object { "$($_.Mes) $($_.Anio)" }) -join '"', ')} | Format-List"

